import sys

s = sys.stdin.read().strip()

for i in range(1, len(s) - 1):
    for j in range(i + 1, len(s)):
        a = s[:i]
        b = s[i:j]
        c = s[j:]
        if a[0] != '0' and b[0] != '0' and c[0] != '0':
            if int(a) + int(b) == int(c):
                print(f"{a}+{b}={c}")
                exit()
